def resolve(path, cwd, links):
    if links is None:
        links = {}

    # Start with the absolute path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]  # Skip the first empty component
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component to current path
        if current == '/':
            next_path = '/' + component
        else:
            next_path = current + '/' + component

        # Check if this path is a symlink
        if next_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[next_path]

            # If target is absolute, start from root
            if target.startswith('/'):
                current = '/'
                new_components = target.split('/')[1:]  # Skip first empty
            else:
                # Target is relative to the directory containing the link
                if next_path == '/':
                    current = '/'
                else:
                    current = next_path.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                new_components = target.split('/')

            # Replace the remaining components with the link target components + rest
            components = new_components + components[i+1:]
            i = 0
            continue

        # Not a symlink, just move to the next path
        current = next_path
        i += 1

    # Return result (no trailing slash except for '/')
    if current == '':
        return '/'
    return current

